// Resumen de la planilla para la página del reloj y para JARVIS (herramienta Resumen_del_dia):
// qué toca hoy en el gimnasio con la sobrecarga progresiva de cada ejercicio, las comidas de
// hoy contra los objetivos de la definición y cuánto falta para cada examen.
const tabla = {};
for (const r of $json.valueRanges || []) tabla[r.range.split('!')[0].replace(/'/g, '')] = (r.values || []).slice(1);
const num = v => { const n = parseFloat(String(v ?? '').replace(',', '.')); return isNaN(n) ? 0 : n; };
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
const hoy = $now.setZone('America/Argentina/Buenos_Aires').toFormat('dd/MM/yyyy');
const aFecha = f => { const [d, m, a] = String(f).split('/').map(Number); return (a || 0) * 10000 + (m || 0) * 100 + (d || 0); };

// --- Gimnasio ---
const dias = (tabla.Rutina || []).filter(r => ['Push', 'Pull', 'Piernas'].includes(r[0]));
const registro = (tabla.Registro || []).filter(r => r[0] && r[2]).map((r, i) => ({
  fecha: r[0], dia: r[1] || '', ejercicio: r[2], peso: num(r[3]), series: num(r[4]), reps: String(r[5] ?? ''), notas: r[6] || '', orden: i
})).sort((a, b) => aFecha(a.fecha) - aFecha(b.fecha) || a.orden - b.orden);
const ultimo = registro.length ? registro[registro.length - 1] : null;
let toca = dias[0];
if (ultimo) {
  const i = dias.findIndex(d => d[0] === ultimo.dia);
  if (i >= 0) toca = ultimo.fecha === hoy ? dias[i] : dias[(i + 1) % dias.length];
}
// Rango de repeticiones de la rutina ("3 x 8-12") para la doble progresión.
function rango(txt) { const m = String(txt || '').match(/(\d+)\s*-\s*(\d+)/); return m ? [+m[1], +m[2]] : [8, 12]; }
// Sesiones de un ejercicio: el nombre del registro tiene que coincidir con el de la rutina
// (sin tildes ni mayúsculas); "Hack o sentadilla" acepta cualquiera de las dos.
function sesiones(nombre) {
  const opciones = norm(nombre).split(' o ').map(s => s.trim()).filter(Boolean);
  const n0 = norm(nombre);
  return registro.filter(r => { const x = norm(r.ejercicio); return x === n0 || opciones.some(o => x === o || x.includes(o) || o.includes(x)); });
}
function progreso(nombre, series) {
  const s = sesiones(nombre);
  const [lo, hi] = rango(series);
  if (!s.length) return { nombre, ultimo: null, mejor: null, historia: [], proxima: `Elegí un peso con el que llegues a ${lo}-${hi} reps` };
  const u = s[s.length - 1];
  const reps = (u.reps.match(/\d+/g) || []).map(Number);
  const minReps = reps.length ? Math.min(...reps) : 0;
  const paso = u.peso >= 40 ? 2.5 : u.peso >= 10 ? 2 : 1;
  const fmt = p => String(Math.round(p * 10) / 10).replace('.', ',');
  let proxima;
  if (u.peso > 0 && minReps >= hi) proxima = `${fmt(u.peso + paso)} kg x ${lo} (subí ${fmt(paso)} kg)`;
  else if (u.peso > 0) proxima = `${fmt(u.peso)} kg x ${Math.min(minReps + 1, hi)} (una rep más)`;
  else proxima = `${Math.min(minReps + 1, hi)} reps`;
  return {
    nombre,
    ultimo: { fecha: u.fecha, peso: u.peso, series: u.series, reps: u.reps },
    mejor: Math.max(...s.map(x => x.peso)),
    historia: s.slice(-8).map(x => x.peso),
    proxima
  };
}
const ejercicios = toca ? (toca[2] || '').split(';').map(s => s.trim()).filter(Boolean) : [];
// Todo lo anotado, agrupado por ejercicio (lo último primero), para ver el progreso.
const porEjercicio = {};
for (const r of registro) (porEjercicio[norm(r.ejercicio)] ||= { ejercicio: r.ejercicio, s: [] }).s.push(r);
const historial = Object.values(porEjercicio).map(e => {
  const u = e.s[e.s.length - 1];
  return { ejercicio: e.ejercicio, ultimo: { fecha: u.fecha, peso: u.peso, series: u.series, reps: u.reps },
    mejor: Math.max(...e.s.map(x => x.peso)), primero: e.s[0].peso, sesiones: e.s.length, historia: e.s.slice(-8).map(x => x.peso) };
}).sort((a, b) => aFecha(b.ultimo.fecha) - aFecha(a.ultimo.fecha));

// --- Comidas ---
const obj = {};
for (const r of tabla.Objetivos || []) obj[norm(r[0]).split(' ')[0]] = num(r[1]);
const objetivo = { kcal: obj.kcal || 2350, p: obj.proteina || 168, c: obj.carbos || 269, g: obj.grasas || 67 };
const comidasHoy = (tabla.Comidas || []).filter(r => r[0] === hoy && r[2]).map(r => ({
  hora: r[1] || '', comida: r[2], kcal: num(r[3]), p: num(r[4]), c: num(r[5]), g: num(r[6])
}));
const total = comidasHoy.reduce((t, x) => ({ kcal: t.kcal + x.kcal, p: t.p + x.p, c: t.c + x.c, g: t.g + x.g }), { kcal: 0, p: 0, c: 0, g: 0 });
for (const k in total) total[k] = Math.round(total[k]);

// --- Estudio ---
const materias = (tabla.Materias || []).filter(r => r[0]).map(r => ({
  materia: r[0], evaluacion: r[1] || '', fecha: r[2] || '', faltan: r[3] === '' || r[3] === undefined ? null : Number(r[3]), notas: r[4] || ''
})).filter(m => m.faltan === null || m.faltan >= 0).sort((a, b) => (a.faltan ?? 999) - (b.faltan ?? 999));

return [{ json: {
  hoy,
  toca: toca ? { dia: toca[0], grupo: toca[1] || '', series: toca[3] || '', extras: toca[4] || '',
    ejercicios: ejercicios.map(e => progreso(e, toca[3])) } : null,
  ultimoDia: ultimo ? { fecha: ultimo.fecha, dia: ultimo.dia } : null,
  historial,
  // La próxima de TODOS los ejercicios de la rutina (para JARVIS, aunque no toquen hoy).
  proximas: dias.flatMap(d => (d[2] || '').split(';').map(s => s.trim()).filter(Boolean).map(e => { const x = progreso(e, d[3]); return { dia: d[0], ejercicio: e, proxima: x.proxima, ultimo: x.ultimo }; })),
  comidas: { hoy: comidasHoy, total, objetivo, falta: { kcal: objetivo.kcal - total.kcal, p: objetivo.p - total.p, c: objetivo.c - total.c, g: objetivo.g - total.g } },
  materias
} }];
